import fs from 'node:fs';import path from 'node:path';import {fileURLToPath} from 'node:url';
export function quantiles(values){const sorted=[...values].filter(Number.isFinite).sort((a,b)=>a-b);const q=p=>sorted.length?sorted[Math.max(0,Math.ceil(sorted.length*p)-1)]:null;return {n:sorted.length,p50:q(.5),p95:q(.95),max:q(1)};}
export function analyze(dir){const read=n=>JSON.parse(fs.readFileSync(path.join(dir,n)));const offers=read('offers.json'),browser=read('browser.json'),db=read('final-oracles.json'),samples=read('database-observations.json'),targetId=new URL(read('browser-config.json').url).searchParams.get('conversation');
 const clock=browser.clocks.reduce((a,b)=>a.uncertainty<b.uncertainty?a:b),rows=[];const markers=[...new Set(offers.offers.map(o=>o.marker))];
 for(const marker of markers){const events=offers.offers.filter(o=>o.marker===marker),target=events[0].target,offeredAt=Math.min(...events.map(o=>o.at)),accepted=events.filter(o=>o.status===202),canonical=db.identities.filter(i=>i.rawId===events[0].rawId),messages=db.messages.filter(m=>m.body?.includes(marker)),messageIds=new Set(messages.map(m=>m.id));
  const time=phase=>{const xs=browser.times.filter(t=>t.marker===marker&&t.phase===phase);return xs.length?Math.min(...xs.map(t=>t.at-clock.offset)):null;};
  const visible=time('visibleAfterTwoFrames'),mounted=time('mounted'),ws=browser.frames.filter(f=>f.event==='received'&&f.markers.includes(marker));const seen=samples.find(s=>s.rows.some(r=>r.body?.includes(marker)));const applied=db.applications.filter(a=>events.some(e=>e.data?.receiptId===a.receiptId)&&a.state==='applied');
  rows.push({marker,target,offeredAt,acceptedEnvelopes:accepted.length,identityCount:canonical.length,messageCount:messages.length,associatedCorrectly:messages.every(m=>target?m.conversationId===targetId:m.conversationId!==targetId),browserIdsMatch:browser.times.filter(t=>t.marker===marker).every(t=>messageIds.has(t.id)),firstResponseMs:accepted.length?Math.min(...accepted.map(e=>e.endedAt))-offeredAt:null,firstDbObservationMs:seen?seen.at-offeredAt:null,appliedMs:applied.length?Math.min(...applied.map(a=>Date.parse(a.appliedAt)))-offeredAt:null,wsObservedMs:ws.length?Math.min(...ws.map(w=>w.at-clock.offset))-offeredAt:null,mountedMs:mounted===null?null:mounted-offeredAt,visibleMs:visible===null?null:visible-offeredAt,afterDbObservationMs:visible!==null&&seen?visible-seen.at:null});
 }
 const selected=rows.filter(r=>r.target),admitted=selected.filter(r=>r.acceptedEnvelopes>0),statusCounts={};for(const o of offers.offers)statusCounts[o.status]=(statusCounts[o.status]??0)+1;
 return {directory:dir,offeredCanonical:markers.length,offeredEnvelopes:offers.offers.length,statusCounts,dbMessageCount:db.messages.length,dbIdentityCount:db.identities.length,dbAppliedReceipts:db.applications.filter(a=>a.state==='applied').length,targetOffered:selected.length,targetAdmitted:admitted.length,targetVisible:selected.filter(r=>r.visibleMs!==null).length,missingAdmitted:admitted.filter(r=>r.visibleMs===null).map(r=>r.marker),duplicateCanonical:rows.filter(r=>r.identityCount>1||r.messageCount>1).map(r=>r.marker),wrongAssociation:rows.filter(r=>!r.associatedCorrectly||!r.browserIdsMatch).map(r=>r.marker),unexpectedBackgroundVisible:rows.filter(r=>!r.target&&r.visibleMs!==null).map(r=>r.marker),metrics:Object.fromEntries(['firstResponseMs','firstDbObservationMs','appliedMs','wsObservedMs','mountedMs','visibleMs','afterDbObservationMs'].map(k=>[k,quantiles(admitted.map(r=>r[k]))])),duplicateUiBubbles:Object.entries(browser.maxSimultaneousBubbles??{}).filter(([,n])=>n>1),browserErrors:browser.errors,browserHttpErrors:browser.requests.filter(r=>r.status>=400),externalBrowserRequestsBlocked:browser.requests.filter(r=>r.blockedExternal),clock:{offsetMs:clock.offset,minimumUncertaintyMs:clock.uncertainty,offsetRangeMs:Math.max(...browser.clocks.map(c=>c.offset))-Math.min(...browser.clocks.map(c=>c.offset))},rows};
}
if(process.argv[1]===fileURLToPath(import.meta.url)){const root=path.resolve(process.argv[2]),summary=JSON.parse(fs.readFileSync(path.join(root,'comparison-summary.json')));const slots=summary.slots.map(s=>({...s,analysis:analyze(path.join(root,s.name))}));fs.writeFileSync(path.join(root,'ui-analysis.json'),JSON.stringify({controller:summary.controller,candidate:summary.candidate,pilot:summary.pilot,slots},null,2));console.log(JSON.stringify(slots.map(s=>({variant:s.variant,profile:s.profile,...s.analysis,rows:undefined})),null,2));}
